**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <algorithm>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int tab[7][7];
    for (int i = 0; i < 7; i++)
        for (int j = 0; j < 7; j++)
            plik >> tab[i][j];

    int dx[] = {-1, 1, 0, 0};
    int dy[] = {0, 0, -1, 1};
    int maxArm = 0;

    for (int i = 0; i < 7; i++) {
        for (int j = 0; j < 7; j++) {
            if (tab[i][j] == 1) {
                int minArm = 7;
                for (int d = 0; d < 4; d++) {
                    int len = 0;
                    int ni = i + dx[d], nj = j + dy[d];
                    while (ni >= 0 && ni < 7 && nj >= 0 && nj < 7 && tab[ni][nj] == 1) {
                        len++;
                        ni += dx[d];
                        nj += dy[d];
                    }
                    minArm = min(minArm, len);
                }
                maxArm = max(maxArm, minArm);
            }
        }
    }

    cout << "Najwieksze ramie plusa: " << maxArm << endl;
    return 0;
}
```

**Wyjasnienie**: Dla kazdej jedynki mierzymy ile jedynek jest w kazdym z 4 kierunkow. Ramie plusa = minimum z 4 ramion. Szukamy maximum po calej siatce.

